/* Spotify DNA — near-black entertainment surface, vivid green, pills everywhere */
.theme-spotify-dna {
  --bg: oklch(0.182 0 0);
  --surface: oklch(0.235 0 0);
  --surface-2: oklch(0.277 0 0);
  --fg: oklch(0.985 0 0);
  --fg-muted: oklch(0.767 0 0);
  --accent: oklch(0.765 0.205 151.5); /* #1ED760 — current Spotify green on dark */
  --accent-fg: oklch(0.14 0 0);
  --accent-2: oklch(0.65 0.2 300);
  --line: oklch(1 0 0 / 12%);
  --success: oklch(0.765 0.205 151.5);
  --warning: oklch(0.83 0.16 85);
  --danger: oklch(0.65 0.22 25);

  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 2px 6px oklch(0 0 0 / 50%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 60%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 70%);
  --glow: 0 0 0 2px color-mix(in oklab, var(--accent) 60%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "DM Sans", "Inter", sans-serif;
  --font-body: "DM Sans", "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.035em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  background-image: linear-gradient(180deg, oklch(0.24 0.05 148 / 45%) 0%, transparent 520px);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-spotify-dna h1,
.theme-spotify-dna h2,
.theme-spotify-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 800;
}

.theme-spotify-dna button {
  border-radius: var(--radius-pill);
  font-weight: 700;
  transition: transform 120ms ease, filter 120ms ease;
}

.theme-spotify-dna button:hover {
  transform: scale(1.04);
}

/* signature */
.theme-spotify-dna { --font-ui: var(--font-display); }
.theme-spotify-dna h1 { font-weight: 900; letter-spacing: -0.05em; }
.theme-spotify-dna button { text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; }

/* depth */
.theme-spotify-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-spotify-dna a { color: var(--fg); text-decoration: none; }
.theme-spotify-dna a:hover { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.theme-spotify-dna thead th { font-size: 0.6875rem; font-weight: 500; text-transform: uppercase; letter-spacing: var(--label-tracking); color: var(--fg-muted); border-bottom: 1px solid var(--line); text-align: left; }
.theme-spotify-dna tbody td { border: none; }
.theme-spotify-dna tbody tr:hover td { background: oklch(1 0 0 / 8%); } /* tracklist row wash */
.theme-spotify-dna tbody tr:hover td:first-child { color: var(--accent); } /* now-playing tick */
.theme-spotify-dna input, .theme-spotify-dna select, .theme-spotify-dna textarea { background: oklch(1 0 0 / 10%); border: 1px solid transparent; border-radius: var(--radius-pill); color: var(--fg); }
.theme-spotify-dna input::placeholder, .theme-spotify-dna textarea::placeholder { color: var(--fg-muted); }
.theme-spotify-dna input:focus-visible, .theme-spotify-dna select:focus-visible, .theme-spotify-dna textarea:focus-visible { outline: none; border-color: var(--fg); background: oklch(1 0 0 / 14%); }
.theme-spotify-dna button:active { transform: scale(0.97); filter: brightness(0.88); } /* play-pill press-in */
.theme-spotify-dna kbd { background: oklch(1 0 0 / 12%); color: var(--fg); border-radius: var(--radius-pill); padding: 0.1em 0.55em; font-family: var(--font-mono); font-size: 0.8em; }
.theme-spotify-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-spotify-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-spotify-dna ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 30%); border-radius: 0; }
.theme-spotify-dna ::-webkit-scrollbar-thumb:hover { background: oklch(1 0 0 / 50%); }
.theme-spotify-dna .label-caps { color: var(--fg-muted); font-weight: 700; }
.theme-spotify-dna .themed-border { border-color: var(--accent); }

/* alt mode: paper sleeve — Spotify green kept, darkened for light-ground contrast */
.theme-spotify-dna.alt-mode {
  --bg: oklch(0.98 0.000 0.0);
  --surface: oklch(0.955 0.000 0.0);
  --surface-2: oklch(0.92 0.000 0.0);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --accent: oklch(0.55 0.17 150); /* #1DB954-family, dark enough on white */
  --accent-fg: oklch(0.99 0 0);
  --success: oklch(0.55 0.17 150);
  background-image: linear-gradient(180deg, oklch(0.93 0.05 150 / 55%) 0%, transparent 420px);
}
.theme-spotify-dna.alt-mode tbody tr:hover td { background: oklch(0 0 0 / 5%); }
.theme-spotify-dna.alt-mode input, .theme-spotify-dna.alt-mode select, .theme-spotify-dna.alt-mode textarea { background: oklch(0 0 0 / 6%); }
.theme-spotify-dna.alt-mode input:focus-visible, .theme-spotify-dna.alt-mode select:focus-visible, .theme-spotify-dna.alt-mode textarea:focus-visible { border-color: var(--fg); background: oklch(0 0 0 / 9%); }
.theme-spotify-dna.alt-mode kbd { background: oklch(0 0 0 / 8%); color: var(--fg); }
.theme-spotify-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0 0 0 / 30%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
